// Synthetic landmarks: a neutral face and a posable hand, in the shape MediaPipe
// returns them (normalised x/y), plus a small scene renderer. Used by the unit
// tests and by scripts/eval-detection/generate-fixtures.mjs.
//
// THIS IS NOT REAL DATA. The face is one fixed set of proportions and the hand a
// simple stick model; nothing here has been compared with a camera. It lets us
// pin down what a rule does when the geometry is known, and it is deterministic
// (seeded), so a fixture can be regenerated byte for byte. It must not be
// imported by app code, so it never reaches the production bundle.
//
// Everything is built in PIXELS of a 640x480 frame and divided by the frame size
// at the end, because the rules measure in normalised coordinates where a step
// of 0.1 sideways is longer on screen than a step of 0.1 up (4:3 camera).

import type { Landmark } from './types.ts';
import { FACE_LANDMARKS_USED } from './zones.ts';

export const IMAGE = { width: 640, height: 480 } as const;

// ── random numbers ──────────────────────────────────────────────────────────

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Roughly normal noise with standard deviation 1 (sum of uniforms). */
function gauss(rnd: () => number): number {
  return (rnd() + rnd() + rnd() + rnd() - 2) * Math.sqrt(3);
}

// ── the face ────────────────────────────────────────────────────────────────

/**
 * Where each face-mesh landmark the rules read sits on a neutral face:
 * [s, v] with s across the face (-1 = the subject's right edge, +1 = the left edge,
 * in units of half the face width) and v down it (0 = top of the forehead, 1 = bottom of the chin).
 * Proportions are plausible, not measured.
 */
const FACE_LAYOUT: Readonly<Record<number, readonly [number, number]>> = {
  10: [0, 0], 152: [0, 1],
  234: [-1, 0.5], 454: [1, 0.5],
  1: [0, 0.665], 2: [0, 0.715],
  13: [0, 0.795], 14: [0, 0.815], 17: [0, 0.865],
  61: [-0.3, 0.805], 291: [0.3, 0.805],
  33: [-0.55, 0.455], 133: [-0.3, 0.46], 362: [0.3, 0.46], 263: [0.55, 0.455],
  145: [-0.43, 0.48], 374: [0.43, 0.48],
  105: [-0.42, 0.385], 334: [0.42, 0.385], 107: [-0.18, 0.395], 336: [0.18, 0.395],
};

export interface FaceOptions {
  /** Centre of the face in pixels. */
  cx?: number;
  cy?: number;
  /** Width (234 to 454) and height (10 to 152) in pixels. */
  width?: number;
  height?: number;
  /** Extra shift in pixels, for head movement. */
  dx?: number;
  dy?: number;
}

/** The face-mesh landmarks the rules read, by index, in pixels. */
export function faceInPixels(options: FaceOptions = {}): Map<number, [number, number]> {
  const { cx = 320, cy = 240, width = 170, height = 195, dx = 0, dy = 0 } = options;
  const out = new Map<number, [number, number]>();
  for (const index of FACE_LANDMARKS_USED) {
    const place = FACE_LAYOUT[index];
    if (!place) throw new Error(`synthetic face has no position for landmark ${index}`);
    out.set(index, [cx + dx + place[0] * (width / 2), cy + dy - height / 2 + place[1] * height]);
  }
  return out;
}

/** A full 478-entry face array in normalised coordinates, with every landmark the rules do not read left at the origin. */
export function denseFace(pixels: Map<number, [number, number]>): Landmark[] {
  const face: Landmark[] = Array.from({ length: 478 }, () => ({ x: 0, y: 0 }));
  for (const [index, [x, y]] of pixels) face[index] = { x: x / IMAGE.width, y: y / IMAGE.height };
  return face;
}

/** The neutral face as a ready-to-use normalised landmark array. */
export function neutralFace(options: FaceOptions = {}): Landmark[] {
  return denseFace(faceInPixels(options));
}

/** A named point on the neutral face, in pixels. */
export function facePoint(name: 'mouth' | 'noseTip' | 'noseBase' | 'chinAnchor' | 'foreheadAnchor' | 'cheekRight' | 'cheekLeft'
  | 'eyeRight' | 'eyeLeft' | 'browRight' | 'browLeft' | 'scalpTop' | 'scalpRight' | 'scalpLeft', options: FaceOptions = {}): [number, number] {
  const f = faceInPixels(options);
  const p = (i: number) => f.get(i)!;
  const mid = (a: [number, number], b: [number, number]): [number, number] => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
  const mean3 = (a: [number, number], b: [number, number], c: [number, number]): [number, number] => [(a[0] + b[0] + c[0]) / 3, (a[1] + b[1] + c[1]) / 3];
  const faceH = Math.hypot(p(10)[0] - p(152)[0], p(10)[1] - p(152)[1]);
  const faceW = Math.hypot(p(234)[0] - p(454)[0], p(234)[1] - p(454)[1]);
  switch (name) {
    case 'mouth': return mid(p(13), p(14));
    case 'noseTip': return p(1);
    case 'noseBase': return mid(p(1), p(2));
    case 'chinAnchor': return mid(p(17), p(152));
    case 'foreheadAnchor': return mid(p(10), mid(p(107), p(336)));
    case 'cheekRight': return mean3(p(145), p(61), p(234));
    case 'cheekLeft': return mean3(p(374), p(291), p(454));
    case 'eyeRight': return mid(p(33), p(133));
    case 'eyeLeft': return mid(p(263), p(362));
    case 'browRight': return p(105);
    case 'browLeft': return p(334);
    case 'scalpTop': return [p(10)[0], p(10)[1] - 0.35 * faceH];
    case 'scalpRight': return [p(10)[0] - 0.32 * faceW, p(10)[1] - 0.22 * faceH];
    case 'scalpLeft': return [p(10)[0] + 0.32 * faceW, p(10)[1] - 0.22 * faceH];
  }
}

// ── the hand ────────────────────────────────────────────────────────────────

export type FingerName = 'thumb' | 'index' | 'middle' | 'ring' | 'pinky';

export interface HandOptions {
  side: 'left' | 'right';
  /** Which hand landmark (0 to 20) sits at `at` (pixels). 8 is the index fingertip, 4 the thumb tip. */
  pin: number;
  at: readonly [number, number];
  /** Direction the fingers point, degrees, 0 = towards the right of the frame, -90 = up. */
  angleDeg: number;
  /** 1 is a palm 85 px long, a hand about 175 px from wrist to middle fingertip at arm's length. */
  size?: number;
  /** How far each finger is stretched, 0.25 (curled in) to 1 (straight). Default: all straight. */
  ext?: Partial<Record<FingerName, number>>;
  /** Bring the thumb tip to the index tip. */
  pinch?: boolean;
}

const PALM = 85;
const KNUCKLE_OFFSET: Record<Exclude<FingerName, 'thumb'>, number> = { index: 30, middle: 10, ring: -10, pinky: -28 };
const SEGMENTS: Record<FingerName, readonly [number, number, number]> = {
  thumb: [34, 28, 26],
  index: [40, 24, 19],
  middle: [44, 27, 20],
  ring: [40, 25, 19],
  pinky: [32, 19, 17],
};
const FIRST_LANDMARK: Record<Exclude<FingerName, 'thumb'>, number> = { index: 5, middle: 9, ring: 13, pinky: 17 };

/** The 21 hand landmarks in pixels. */
export function handInPixels(options: HandOptions): Array<[number, number]> {
  const { side, pin, at, angleDeg, size = 1, ext = {}, pinch = false } = options;
  const a = (angleDeg * Math.PI) / 180;
  const dir = [Math.cos(a), Math.sin(a)] as const;
  const sign = side === 'right' ? 1 : -1;
  const perp = [-dir[1] * sign, dir[0] * sign] as const;
  const e = (f: FingerName) => Math.min(1, Math.max(0.25, ext[f] ?? 1));

  const pts: Array<[number, number]> = Array.from({ length: 21 }, () => [0, 0]);
  const at2 = (origin: readonly [number, number], d: readonly [number, number], length: number): [number, number] =>
    [origin[0] + d[0] * length, origin[1] + d[1] * length];

  pts[0] = [0, 0];
  const base = at2([0, 0], dir, PALM * size);

  for (const finger of ['index', 'middle', 'ring', 'pinky'] as const) {
    const mcp = at2(base, perp, KNUCKLE_OFFSET[finger] * size);
    const [l1, l2, l3] = SEGMENTS[finger];
    const k = e(finger) * size;
    const first = FIRST_LANDMARK[finger];
    pts[first] = mcp;
    pts[first + 1] = at2(mcp, dir, l1 * k);
    pts[first + 2] = at2(mcp, dir, (l1 + l2) * k);
    pts[first + 3] = at2(mcp, dir, (l1 + l2 + l3) * k);
  }

  // Thumb: from near the wrist, angled 40 degrees towards the index side.
  const cmc = at2(at2([0, 0], dir, 18 * size), perp, 22 * size);
  const ta = a + (40 * Math.PI) / 180 * sign;
  let tdir: readonly [number, number] = [Math.cos(ta), Math.sin(ta)];
  const [t1, t2, t3] = SEGMENTS.thumb;
  let scale = e('thumb') * size;
  if (pinch) {
    const target = pts[8];
    const reach = Math.hypot(target[0] - cmc[0], target[1] - cmc[1]);
    tdir = [(target[0] - cmc[0]) / reach, (target[1] - cmc[1]) / reach];
    scale = reach / (t1 + t2 + t3);
  }
  pts[1] = cmc;
  pts[2] = at2(cmc, tdir, t1 * scale);
  pts[3] = at2(cmc, tdir, (t1 + t2) * scale);
  pts[4] = at2(cmc, tdir, (t1 + t2 + t3) * scale);
  if (pinch) pts[4] = [pts[8][0] + 2 * dir[0] * sign, pts[8][1] + 2 * dir[1] * sign];

  // Move the whole hand so the pinned landmark lands on `at`.
  const shift: [number, number] = [at[0] - pts[pin][0], at[1] - pts[pin][1]];
  return pts.map(([x, y]) => [x + shift[0], y + shift[1]] as [number, number]);
}

export function toNormalised(points: ReadonlyArray<readonly [number, number]>): Landmark[] {
  return points.map(([x, y]) => ({ x: x / IMAGE.width, y: y / IMAGE.height }));
}

/** A hand as MediaPipe would return it (21 normalised landmarks). */
export function buildHand(options: HandOptions): Landmark[] {
  return toNormalised(handInPixels(options));
}

// ── scenes ──────────────────────────────────────────────────────────────────

export interface PathKey {
  /** Milliseconds from the start. */
  t: number;
  /** Pixels. Put it below the frame (y above 560) to have the hand out of view. */
  at: readonly [number, number];
}

export interface HandTrack {
  side: 'left' | 'right';
  /** Landmark that follows the path. */
  pin: number;
  path: readonly PathKey[];
  angleDeg: number;
  size?: number;
  ext?: Partial<Record<FingerName, number>>;
  /** Intervals (ms) with the thumb and index tips together. `true` = the whole time. */
  pinch?: boolean | ReadonlyArray<readonly [number, number]>;
  /** A steady back-and-forth added to the pinned point during [from, to]. Amplitude in pixels. */
  wobble?: { amp: readonly [number, number]; hz: number; from: number; to: number };
  /** Landmark noise, pixels (standard deviation). Default 0.8, about what a tracker adds. */
  jitterPx?: number;
}

export interface Label {
  /** Behaviours for which an alarm in this interval is correct. */
  behaviors: string[];
  startMs: number;
  endMs: number;
}

export interface Scene {
  id: string;
  description: string;
  tags: string[];
  seed: number;
  durationMs: number;
  hands: HandTrack[];
  labels: Label[];
  face?: FaceOptions;
  /** The head drifts by this much (pixels) at this rate. */
  headSway?: { amp: readonly [number, number]; hz: number };
  /** Intervals (ms) in which no face is detected. */
  noFace?: ReadonlyArray<readonly [number, number]>;
  /** Plain words: a place where the rules are expected to be wrong, and why. */
  knownIssue?: string;
}

export const FRAME_MS = 200;

const smooth = (u: number) => u * u * (3 - 2 * u);

function samplePath(path: readonly PathKey[], t: number): [number, number] | null {
  if (path.length === 0 || t < path[0].t || t > path[path.length - 1].t) return null;
  for (let i = 1; i < path.length; i++) {
    if (t <= path[i].t) {
      const a = path[i - 1];
      const b = path[i];
      const u = b.t === a.t ? 1 : smooth((t - a.t) / (b.t - a.t));
      return [a.at[0] + (b.at[0] - a.at[0]) * u, a.at[1] + (b.at[1] - a.at[1]) * u];
    }
  }
  return [...path[path.length - 1].at] as [number, number];
}

export interface RenderedFrame {
  t: number;
  hands: Landmark[][];
  /** Null = no face this frame. */
  face: Map<number, [number, number]> | null;
}

/** Renders a scene to frames. Deterministic for a given scene. */
export function renderScene(scene: Scene): RenderedFrame[] {
  const rnd = mulberry32(scene.seed);
  const frames: RenderedFrame[] = [];

  for (let t = 0; t <= scene.durationMs; t += FRAME_MS) {
    // Face
    let face: Map<number, [number, number]> | null = null;
    const hidden = scene.noFace?.some(([a, b]) => t >= a && t <= b) ?? false;
    if (!hidden) {
      const sway = scene.headSway;
      const dx = sway ? sway.amp[0] * Math.sin(2 * Math.PI * sway.hz * (t / 1000)) : 0;
      const dy = sway ? sway.amp[1] * Math.sin(2 * Math.PI * sway.hz * (t / 1000) + 1.3) : 0;
      face = faceInPixels({ ...scene.face, dx: (scene.face?.dx ?? 0) + dx, dy: (scene.face?.dy ?? 0) + dy });
    }

    // Hands
    const hands: Landmark[][] = [];
    for (const track of scene.hands) {
      const p = samplePath(track.path, t);
      if (!p) continue;
      let [x, y] = p;
      const w = track.wobble;
      if (w && t >= w.from && t <= w.to) {
        const phase = 2 * Math.PI * w.hz * ((t - w.from) / 1000);
        x += w.amp[0] * Math.sin(phase);
        y += w.amp[1] * Math.sin(phase * 1.31 + 0.7);
      }
      const pinching = track.pinch === true || (Array.isArray(track.pinch) && track.pinch.some(([a, b]) => t >= a && t <= b));
      const px = handInPixels({
        side: track.side, pin: track.pin, at: [x, y], angleDeg: track.angleDeg,
        size: track.size, ext: track.ext, pinch: pinching,
      });
      // A hand is only seen once its wrist is inside the frame.
      if (px[0][1] > IMAGE.height - 10) continue;
      const sigma = track.jitterPx ?? 0.8;
      hands.push(toNormalised(px.map(([hx, hy]) => [hx + gauss(rnd) * sigma, hy + gauss(rnd) * sigma] as [number, number])));
    }
    frames.push({ t, hands, face });
  }
  return frames;
}
